#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# ── NOSION · Phase 4 ขั้น 8 — ส่งการเตือนจาก API บน Vercel (ไม่มี worker) โดยให้ cron-job.org เรียกทุกนาที ──
# รันจากรากของ repo: bash scripts/vercel-cron-setup.sh
# ใช้ไฟล์เก็บค่าเดียวกับ scripts/fly-staging-setup.sh — กุญแจ VAPID ชุดเดียวกัน ย้ายไป worker ภายหลังได้โดยผู้ใช้ไม่ต้องเปิดการแจ้งเตือนใหม่
ENV_FILE=".env.staging.fly"
TOTAL_STAGES=6
STAGING_WEB="https://nosion-staging-web.vercel.app"

[[ -f apps/api/src/notifications/notifications-cron.controller.ts ]] || { warn "รันจากรากของ repo NOSION"; exit 1; }

copy() {
  if command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}
vercel_var() {
  local name="$1" value="$2"
  if copy "$value"; then step "เพิ่ม/แก้ ${BOLD}$name${RESET} → วางค่า (คัดลอกลง clipboard แล้ว)"
  else step "เพิ่ม/แก้ $name = $value"; fi
  pause "เสร็จแล้วกด Enter"
}

banner "NOSION staging · การเตือนผ่าน Vercel + cron-job.org"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "สร้างกุญแจ Web Push (VAPID) + secret ของปุ่มใน notification"
say "สร้างครั้งเดียวแล้วใช้ตลอด — เปลี่ยนภายหลัง = ทุกเครื่องต้องกดเปิดการแจ้งเตือนใหม่"
VAPID_PUBLIC_KEY=$(_existing VAPID_PUBLIC_KEY || true)
VAPID_PRIVATE_KEY=$(_existing VAPID_PRIVATE_KEY || true)
if [[ -z "$VAPID_PUBLIC_KEY" || -z "$VAPID_PRIVATE_KEY" ]]; then
  pair=$(node -e "
    const e = require('crypto').createECDH('prime256v1'); e.generateKeys();
    const p = e.getPrivateKey(); const pad = Buffer.concat([Buffer.alloc(32 - p.length), p]);
    console.log(e.getPublicKey().toString('base64url') + ' ' + pad.toString('base64url'));")
  VAPID_PUBLIC_KEY=${pair% *}; VAPID_PRIVATE_KEY=${pair#* }
  note "สร้างคู่กุญแจใหม่แล้ว"
else
  note "ใช้คู่กุญแจเดิมจาก $ENV_FILE"
fi
write_env VAPID_PUBLIC_KEY "$VAPID_PUBLIC_KEY"
write_env VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
ask VAPID_SUBJECT "อีเมลติดต่อสำหรับ push service (mailto:…):" || true
[[ "$VAPID_SUBJECT" == mailto:* ]] || VAPID_SUBJECT="mailto:${VAPID_SUBJECT:-pongsathorn.junt@gmail.com}"
write_env VAPID_SUBJECT "$VAPID_SUBJECT"
NOTIFICATION_ACTION_SECRET=$(_existing NOTIFICATION_ACTION_SECRET || true)
[[ -n "$NOTIFICATION_ACTION_SECRET" ]] || NOTIFICATION_ACTION_SECRET=$(openssl rand -hex 32)
write_env NOTIFICATION_ACTION_SECRET "$NOTIFICATION_ACTION_SECRET"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "CRON_SECRET — สร้างใหม่แล้วตั้งบน Vercel (Production)"
say "ค่าเดิมเป็นแบบ Sensitive — Vercel ไม่ให้เปิดดูหลังบันทึก จึงสร้างค่าใหม่ แล้วใช้ค่าเดียวกันทั้ง Vercel และ cron-job.org"
note "ปลอดภัย: Vercel Cron ของรอบบิล (/internal/cron/recurrence) อ่านค่าจาก env เอง ไม่มีที่อื่นต้องตามแก้"
CRON_SECRET=$(_existing CRON_SECRET || true)
if [[ -n "$CRON_SECRET" ]] && ! confirm "มี CRON_SECRET ที่ wizard สร้างไว้แล้ว — สร้างใหม่ทับไหม (ตอบ N = ใช้ค่าเดิม)"; then
  note "ใช้ค่าเดิมจาก $ENV_FILE"
else
  CRON_SECRET=$(openssl rand -hex 32)
  note "สร้างค่าใหม่แล้ว (64 ตัว)"
fi
write_env CRON_SECRET "$CRON_SECRET"
open_url "https://vercel.com/dashboard"
step "project nosion-staging-api → Settings → Environment Variables → แถว CRON_SECRET → ⋯ → Edit"
step "Environments: ติ๊ก ${BOLD}Production${RESET} (และ Preview ได้) — ตอนนี้ติ๊กแค่ Preview ทำให้ staging ไม่เห็นค่า"
step "Value: ลบค่าเดิมแล้ววางค่าใหม่ · ยังเป็นแบบ Sensitive ได้ · กด Save"
copy "$CRON_SECRET" && note "(ค่าใหม่คัดลอกลง clipboard แล้ว)" || note "ค่า: $CRON_SECRET"
pause "บันทึกแล้วกด Enter"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "อีเมล: log หรือ Resend"
say "log = บันทึกลง log ไม่ส่งจริง (push ใช้ได้ปกติ) · resend = ส่งจริง ต้องยืนยันโดเมนใน Resend แล้ว"
MAIL_DRIVER=log
if confirm "ใช้ Resend ส่งอีเมลจริงไหม (ตอบ N = log)"; then
  MAIL_DRIVER=resend
  open_url "https://resend.com/api-keys"
  step "Create API Key → Sending access → คัดลอก (ขึ้นต้น re_)"
  ask_secret RESEND_API_KEY "วาง RESEND_API_KEY:"
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  ask EMAIL_FROM "EMAIL_FROM (เช่น NOSION <noreply@yourdomain.com>):"
  write_env EMAIL_FROM "$EMAIL_FROM"
fi
write_env MAIL_DRIVER "$MAIL_DRIVER"
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Vercel: env ของ project API (Production)"
open_url "https://vercel.com/dashboard"
step "project API → Settings → Environment Variables → แต่ละตัวเลือก Environment = Production"
vercel_var VAPID_PUBLIC_KEY "$VAPID_PUBLIC_KEY"
vercel_var VAPID_PRIVATE_KEY "$VAPID_PRIVATE_KEY"
vercel_var VAPID_SUBJECT "$VAPID_SUBJECT"
vercel_var NOTIFICATION_ACTION_SECRET "$NOTIFICATION_ACTION_SECRET"
vercel_var MAIL_DRIVER "$MAIL_DRIVER"
if [[ "$MAIL_DRIVER" == resend ]]; then
  vercel_var RESEND_API_KEY "$RESEND_API_KEY"
  vercel_var EMAIL_FROM "$EMAIL_FROM"
fi
note "ลิงก์ในอีเมล (เปิดแอป / เลิกรับ) สร้างจาก APP_URL และ API_URL — ทั้งคู่ต้องเป็นโดเมนของเว็บ (API อยู่หลัง proxy)"
vercel_var APP_URL "$STAGING_WEB"
vercel_var API_URL "$STAGING_WEB"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Redeploy API ให้อ่าน env ใหม่"
say "env ของ Vercel มีผลกับ deploy ถัดไปเท่านั้น"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 && confirm "สั่ง Deploy staging ผ่าน GitHub Actions ตอนนี้ไหม"; then
  gh workflow run "Deploy staging"
  note "รอให้เสร็จ (~3–5 นาที) — ดูได้ด้วย: gh run watch"
  sleep 5
  gh run watch "$(gh run list --workflow 'Deploy staging' --limit 1 --json databaseId --jq '.[0].databaseId')" --exit-status \
    || warn "Deploy ไม่ผ่าน — เปิด GitHub Actions ดู log ก่อนไปขั้นถัดไป"
else
  step "GitHub → Actions → Deploy staging → Run workflow (หรือกด Redeploy ที่ project API บน Vercel)"
  pause "deploy เสร็จแล้วกด Enter"
fi
# ตรวจจากภายนอก: endpoint ตอบด้วย secret ที่ถูก และ API มี public key แล้ว
code=$(curl -s -o /dev/null -w '%{http_code}' -H "Authorization: Bearer $CRON_SECRET" "$STAGING_WEB/api/v1/internal/cron/reminders")
if [[ "$code" == 200 ]]; then printf '  %s✓%s /internal/cron/reminders ตอบ 200\n' "$GREEN" "$RESET"
else warn "/internal/cron/reminders ตอบ $code (ควรเป็น 200 — 401 = CRON_SECRET ไม่ตรง · 404 = ยังไม่ได้ deploy โค้ดใหม่)"; fi
token=$(curl -s -X POST "$STAGING_WEB/api/v1/auth/demo" | node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{try{console.log(JSON.parse(s).accessToken)}catch{}})")
key=$(curl -s -H "Authorization: Bearer $token" "$STAGING_WEB/api/v1/push/config")
if [[ "$key" == *"$VAPID_PUBLIC_KEY"* ]]; then printf '  %s✓%s API ส่ง VAPID public key ให้เบราว์เซอร์แล้ว\n' "$GREEN" "$RESET"
else warn "API ยังไม่ส่ง public key ($key) — ตรวจว่าตั้ง VAPID_PUBLIC_KEY แบบ Production และ deploy ใหม่แล้ว"; fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "cron-job.org: เรียก endpoint ตามรอบ"
say "Vercel Cron แผน Hobby รันได้วันละครั้ง — ให้ cron-job.org (ฟรี) เรียกแทน"
open_url "https://console.cron-job.org/jobs/create"
say "งานที่ 1 — การเตือน (ทุก 1 นาที):"
step "Title: NOSION reminders"
copy "$STAGING_WEB/api/v1/internal/cron/reminders" && note "(URL คัดลอกลง clipboard แล้ว)"
step "URL: $STAGING_WEB/api/v1/internal/cron/reminders"
step "Execution schedule: Every 1 minute"
step "แท็บ ADVANCED → Headers → Add: Key = Authorization · Value = Bearer <CRON_SECRET>"
copy "Bearer $CRON_SECRET" && note "(ค่า 'Bearer …' คัดลอกลง clipboard แล้ว — วางในช่อง Value)"
step "Request method: GET · Timeout 30 วินาที · กด CREATE"
pause "สร้างงานที่ 1 แล้วกด Enter"
say "งานที่ 2 — สรุปรายวัน (ทุก 15 นาที — แต่ละคนได้ตาม 07:00 ของโซนตัวเอง):"
copy "$STAGING_WEB/api/v1/internal/cron/digest" && note "(URL คัดลอกลง clipboard แล้ว)"
step "Title: NOSION digest · URL: $STAGING_WEB/api/v1/internal/cron/digest"
step "Execution schedule: Every 15 minutes · header Authorization เหมือนงานที่ 1"
copy "Bearer $CRON_SECRET" || true
pause "สร้างงานที่ 2 แล้วกด Enter"
step "เปิดงานที่ 1 → History: รายการล่าสุดควรเป็น 200 OK และ body มี \"sent\""
say "พร้อมทดสอบบนมือถือ: $STAGING_WEB/settings → เปิดการแจ้งเตือน → กด 'ส่งทดสอบ'"
note "ควรเด้งภายใน ~2–3 นาที (นอกช่วงห้ามรบกวน) · กด 'เสร็จแล้ว' จาก notification แล้วงานในหน้า Tasks ต้องเป็นเสร็จ"
pause "กด Enter เพื่อดูสรุป"

finish
}

run_wizard "$@"; exit
